{
  "schema_version": 1,
  "action": "set_policy",
  "policy": {
    "model": "ae",
    "window": 3,
    "threshold_q": 0.999,
    "persistence": 3
  },
  "intent_understood_as": "early_attack_detection",
  "reason": "Intent 'catch anything fast' maps to early_attack_detection (hard budget ≤1.0 false alarms/hour). Only ae detects novel attacks (GTP-U). ae w3 default gives 24.34/h, violating budget. Raising threshold_q to 0.999 and persistence to 3 cuts ae false alarms to ~7.7/h at persistence 3 alone; q0.999 further reduces them below 1.0/h while preserving novel-attack detection, satisfying the budget with the fastest possible confirmation."
